/* Player dossier, shared by every roster and free agent. */
let activePlayerId=null,playerTab='Overview';
const PLAYER_TABS=['Overview','Stats','Attributes','Tendencies','Development','Contract'];
const POSITION_NAMES={PG:'Point guard',SG:'Shooting guard',SF:'Small forward',PF:'Power forward',C:'Center'};
function playerContext(id){const club=state.teams.find(t=>t.roster.some(p=>p.id===id));const p=club?club.roster.find(p=>p.id===id):state.free.find(p=>p.id===id);return p?{p,club,own:club?.id===controlledTeamId(),starter:club?club.roster.indexOf(p)<5:false}:null}
function openPlayerProfile(id){if(!playerContext(id))return;activePlayerId=id;playerTab='Overview';renderPlayerProfile();const d=document.getElementById('profile');if(!d.open)d.showModal()}
function changePlayerTab(tab){if(!PLAYER_TABS.includes(tab))return;playerTab=tab;renderPlayerProfile();document.getElementById('player-tab-'+tab)?.focus()}
function playerTabKeys(event){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let i=PLAYER_TABS.indexOf(playerTab);changePlayerTab(PLAYER_TABS[event.key==='Home'?0:event.key==='End'?PLAYER_TABS.length-1:(i+(event.key==='ArrowRight'?1:PLAYER_TABS.length-1))%PLAYER_TABS.length])}
function playerSilhouette(){return `<svg viewBox="0 0 24 24" role="img" aria-label="Player silhouette"><path fill="currentColor" d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>`}
function playerNumbers(p){return `<div class="pp-numbers">${[['GP',p.gp],['PPG',p.gp?(p.pts/p.gp).toFixed(1):'—'],['RPG',p.gp?(p.reb/p.gp).toFixed(1):'—'],['APG',p.gp?(p.ast/p.gp).toFixed(1):'—']].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>`}
function playerCard(title,body){return `<section class="pp-card"><h3>${title}</h3>${body}</section>`}
function playerOverview({p,club,starter}){return `<div class="pp-summary"><h3>${p.ovr>=85?'A leading talent.':p.ovr>=75?'A strong rotation piece.':'A player with a role to earn.'}</h3><p>${escapeHTML(p.name)} ${club?'plays for '+escapeHTML(club.city+' '+club.name):'is available in free agency'} at ${POSITION_NAMES[p.pos].toLowerCase()}. ${p.pot>p.ovr?'Rated '+p.ovr+' overall with a potential ceiling of '+p.pot+'.':'Currently rated '+p.ovr+' overall.'}</p></div>${playerBioFacts(p)}${internationalPlayerInfo(p)}${playerCard('QUICK STATS · CURRENT SEASON',playerNumbers(p))}<div class="pp-two">${playerCard(club?'SALARY':'ASKING SALARY',`<strong class="pp-value">${money(club?p.salary:freeAgentQuote(p))} / year</strong><p>${club?'On roster':'Available to sign'}</p>`)}${playerCard('DEVELOPMENT',`<strong class="pp-value">${ratingMarkup(p.pot)} potential</strong><p>${Math.max(0,p.pot-p.ovr)} points above current rating</p>`)}</div>`}
function playerGameRows(p){return state.history.flatMap(h=>h.box.filter(b=>b.playerId===p.id).map(b=>({...b,day:h.day,stage:h.stage,opponent:state.teams[h.a].abbr===b.team?state.teams[h.b].abbr:state.teams[h.a].abbr}))).reverse()}
function playerStats({p}){const games=playerGameRows(p).filter(g=>g.played!==false&&(profileCompetitionMatches(g.stage))),summary=profileStatsStage==='all'?p:{gp:games.length,pts:games.reduce((n,g)=>n+g.pts,0),reb:games.reduce((n,g)=>n+g.reb,0),ast:games.reduce((n,g)=>n+g.ast,0)},competition=profileStatsStage==='playoffs'?'Playoffs':profileStatsStage==='regular'?'Regular Season':'All competitions',recent=games.slice(-15),max=Math.max(1,...recent.map(g=>g.pts));return `<div class="pp-section-title"><h3>Season stats (${state.year})</h3><span>${competition}</span></div>${playerNumbers(summary)}${playerCard('SCORING BY GAME',recent.length?`<div class="pp-chart" role="img" aria-label="Points in the last ${recent.length} recorded games: ${recent.map(g=>g.pts).join(', ')}"><span class="pp-chart-max">${max} PTS</span>${recent.map(g=>`<div title="Day ${g.day} vs ${escapeHTML(g.opponent)}: ${g.pts} points"><b style="height:${Math.max(2,g.pts/max*100)}%"></b><small>${g.day}</small></div>`).join('')}</div><p>Last ${recent.length} recorded games · day numbers below</p>`:`<p>No recorded ${competition.toLowerCase()} appearances this season.</p>`)}<div class="pp-two">${playerCard(competition.toUpperCase()+' TOTALS',`<dl class="pp-ledger"><div><dt>Points</dt><dd>${summary.pts}</dd></div><div><dt>Rebounds</dt><dd>${summary.reb}</dd></div><div><dt>Assists</dt><dd>${summary.ast}</dd></div></dl>`)}${playerCard('GAMES PLAYED',`<strong class="pp-value">${summary.gp}</strong><p>${competition} · recorded appearances only.</p>`)}</div>${profileGameLogCard(p,games)}`}
function playerDevelopment({p}){return archetypeDevelopmentCard(p)+`${playerCard('CURRENT ABILITY & POTENTIAL',`<div class="pp-rating-bars">${[['Overall',p.ovr],['Potential',p.pot]].map(([label,n])=>`<div><span>${label}</span><meter class="rating-meter rating-${ratingTier(n)[0]}" min="0" max="99" value="${n}">${n}</meter><strong>${ratingMarkup(n)}</strong></div>`).join('')}</div><p>Potential is a ceiling, not a guaranteed future rating.</p>`)}<div class="pp-two">${playerCard('ROOM TO GROW',`<strong class="pp-value">+${Math.max(0,p.pot-p.ovr)}</strong><p>Rating points to potential</p>`)}${playerCard('AGE',`<strong class="pp-value">${p.age}</strong><p>${p.age<25?'Early development years':p.age>29?'Veteran stage':'Prime years'}</p>`)}</div>${playerCard('OFFSEASON DEVELOPMENT','<p>Overall ratings update when a new season begins. Younger players have more room for improvement, while older players can decline. Development varies each season and is capped by potential.</p>')}`}
function playerContract({p,club,own}){return `${playerCard(club?'ANNUAL SALARY':'FREE AGENT ASKING SALARY',`<strong class="pp-salary">${money(p.salary)} <small>/ year</small></strong><p>${club?escapeHTML(club.city+' '+club.name):'Unsigned · available now'}</p>`)}${playerCard('YOUR TEAM FINANCES',`<dl class="pp-ledger"><div><dt>Salary cap</dt><dd>${money(salaryCap())}</dd></div><div><dt>Current payroll</dt><dd>${money(payroll())}</dd></div><div><dt>Available cap space</dt><dd>${money(salaryCap()-payroll())}</dd></div>${!club?`<div><dt>Cap space after signing</dt><dd>${money(salaryCap()-payroll()-p.salary)}</dd></div>`:''}</dl>`)}${playerCard('CONTRACT RULES',`<p>Salaries carry forward each season. Contract years and options are not currently simulated. ${own?'Releasing this player clears their salary immediately.':'Your team must stay under the hard salary cap to acquire a player.'}</p>`)}`}
function renderPlayerProfile(){const ctx=playerContext(activePlayerId);if(!ctx)return;const {p,club,own,starter}=ctx,d=document.getElementById('profile');d.className='player-dialog player-fullscreen';d.setAttribute('aria-labelledby','pp-name');d.innerHTML=`<button class="pp-close" onclick="document.getElementById('profile').close()" aria-label="Close player profile">×</button><header class="pp-header"><div class="pp-portrait">${playerSilhouette()}</div><div class="pp-identity"><h2 id="pp-name">${escapeHTML(p.name)}</h2><p>${POSITION_NAMES[p.pos]} <span> | </span> Age ${p.age}</p><div class="pp-club">${club?teamLogo(club):''}<span>${club?escapeHTML(club.city+' '+club.name):'Free agent'}</span></div><span class="pp-role">${club?starter?'Starter':'Bench':'Unsigned'}</span><span class="pp-archetype">${escapeHTML(archetypeProfile(p).name)}</span></div><div class="pp-ratings"><span>OVR</span><strong>${ratingMarkup(p.ovr)}</strong><span>POT</span><b>${ratingMarkup(p.pot)}</b></div></header><div class="pp-tabs" role="tablist" aria-label="Player details" onkeydown="playerTabKeys(event)">${PLAYER_TABS.map(tab=>`<button id="player-tab-${tab}" role="tab" aria-selected="${tab===playerTab}" aria-controls="pp-content" tabindex="${tab===playerTab?0:-1}" onclick="changePlayerTab('${tab}')">${tab}</button>`).join('')}</div><div class="pp-content" id="pp-content" role="tabpanel" aria-labelledby="player-tab-${playerTab}" tabindex="0">${({Overview:playerOverview,Stats:playerStats,Attributes:playerAttributes,Tendencies:playerTendencies,Development:playerDevelopment,Contract:playerContract,Family:familyProfileTab})[playerTab](ctx)}</div><footer class="pp-actions">${own?`<button class="primary" onclick="playerLineupAction(${p.id})">${starter?'Move to bench':'Start player'}</button><button onclick="playerTradeAction(${p.id})">Trade</button><button onclick="extendPlayerContract(${p.id})">Extend</button><button onclick="playerReleaseAction(${p.id})" ${team().roster.length<=rosterMinimum()?'disabled':''}>Release</button>`:club?`<button class="primary" onclick="playerTradeAction(${p.id})">Trade for player</button>`:`<button class="primary" onclick="playerSignAction(${p.id})" ${!faActive()&&(payroll()+freeAgentQuote(p)>financeRosterLimit()||team().roster.length>=rosterMaximum())?'disabled':''}>${faActive()?'Negotiate':'Sign · '+money(freeAgentQuote(p))+' / year'}</button>`}<button onclick="document.getElementById('profile').close()">Close</button></footer>`}
function playerLineupAction(id){const c=playerContext(id);if(!c?.own)return;if(!c.starter)promote(id);else{const r=team().roster,i=r.indexOf(c.p);let j=r.findIndex((p,k)=>k>=5&&p.pos===c.p.pos);if(j<0)j=5;if(rotationValid(team()))[r[i].rotationMinutes,r[j].rotationMinutes]=[r[j].rotationMinutes,r[i].rotationMinutes];[r[i],r[j]]=[r[j],r[i]];syncRotationAfterLineupChange();save();render();toast('Starting lineup updated')}renderPlayerProfile()}
function playerSignAction(id){if(faActive())return faOfferDialog(id);sign(id);renderPlayerProfile()}
function playerReleaseAction(id){if(!playerContext(id)?.own)return;releasePlayer(id);renderPlayerProfile()}
function playerTradeAction(id){const c=playerContext(id);if(!c?.club)return;document.getElementById('profile').close();go('Trades');document.getElementById(c.own?'out':'into').value=String(id)}
function browseLeaguePlayers(value){const id=Number(value),club=state.teams.find(t=>t.id===id)||team();return `<div class="panel"><div class="panelhead"><h2>League players</h2><label>Team <select onchange="document.getElementById('league-player-browser').innerHTML=browseLeaguePlayers(this.value)">${state.teams.map(t=>`<option value="${t.id}" ${t.id===club.id?'selected':''}>${escapeHTML(t.city+' '+t.name)}</option>`).join('')}</select></label></div><div class="scroll"><table><thead><tr><th>Player</th><th>POS</th><th>AGE</th><th>OVR</th><th>POT</th></tr></thead><tbody>${club.roster.map(p=>`<tr><td><button class="namebutton" onclick="profile(${p.id})">${escapeHTML(p.name)}</button></td><td>${p.pos}</td><td>${p.age}</td><td>${ratingMarkup(p.ovr)}</td><td>${ratingMarkup(p.pot)}</td></tr>`).join('')}</tbody></table></div></div>`}

// Full-season game logs: once the regular season ends (and once a player's playoff run is over), the profile offers the
// complete regular-season and playoff logs alongside the recent-games view.
let profileGameLog={id:null,scope:'recent'};
function profileLogScope(p){if(profileGameLog.id!==p.id)profileGameLog={id:p.id,scope:'recent'};return profileGameLog.scope}
function setProfileGameLog(scope){if(['recent','regular','playoffs'].includes(scope)){profileGameLog.scope=scope;renderPlayerProfile()}}
function profileSeasonGames(p,playoffs){return state.history.map((h,index)=>({h,index})).reverse().filter(({h})=>(h.stage==='Regular season')!==playoffs).flatMap(({h,index})=>h.box.filter(b=>b.playerId===p.id&&b.played!==false).map(b=>{const home=state.teams[h.a].abbr===b.team,own=home?h.sa:h.sb,opp=home?h.sb:h.sa;return {...b,index,day:h.day,stage:h.stage,home,opponent:state.teams[home?h.b:h.a].abbr,result:(own>opp?'W ':'L ')+own+'–'+opp}}))}
function profilePlayoffRunOver(games){if(state.champion!==null)return true;const last=games.at(-1);if(!last)return false;const team=state.teams.find(t=>t.abbr===last.team);return !!team&&playoffSeriesSlots().some(s=>s.complete&&s.pair?.includes(team.id)&&s.winner!==team.id)}
function profileGameLogShortcuts(p){const regular=state.day>=seasonLength()?profileSeasonGames(p,false):[],playoffs=profileSeasonGames(p,true);return {regular:regular.length?regular:null,playoffs:playoffs.length&&profilePlayoffRunOver(playoffs)?playoffs:null}}
function showProfileLogGame(index,id){if(!state.history[index])return;showResult(index);document.getElementById('profile').innerHTML+=`<button class="primary" style="margin-top:16px" onclick="Promise.resolve(openPlayerProfile(${id})).then(()=>changePlayerTab('Stats'))">Back to game log</button>`}
function profileFullGameLog(p,games,label){return `<div class="scroll pp-game-log" tabindex="0" role="region" aria-label="${escapeHTML(label)} game log; scroll horizontally for all statistics"><table><thead><tr><th scope="col">G</th><th scope="col">Day</th><th scope="col"></th><th scope="col">Opp</th><th scope="col">Result</th>${gameBoxStatHeaders()}<th scope="col">Box</th></tr></thead><tbody>${games.map((g,i)=>`<tr><td>${i+1}</td><td>${g.day}</td><td>${g.home?'':'@'}</td><td>${escapeHTML(g.opponent)}</td><td>${escapeHTML(g.result)}</td>${gameBoxStatCells(g)}<td><button class="namebutton" onclick="showProfileLogGame(${g.index},${p.id})">Box score</button></td></tr>`).join('')}</tbody></table></div><p>${games.length} ${games.length===1?'game':'games'} played. @ = away game. FG, 3PT and FT show makes–attempts. STA% is stamina at the end of the game.</p>`}
function profileGameLogCard(p,games){
 const links=profileGameLogShortcuts(p),scope=profileLogScope(p),season=typeof awardSeasonLabel==='function'?awardSeasonLabel(state.year):String(state.year);
 const active=scope!=='recent'&&links[scope]?scope:'recent';if(!games.length&&!links.regular&&!links.playoffs)return '';
 const button=(key,label)=>`<button type="button" ${active===key?'class="primary" aria-pressed="true"':'aria-pressed="false"'} onclick="setProfileGameLog('${key}')">${label}</button>`;
 const nav=links.regular||links.playoffs?`<div class="actions pp-log-links" role="group" aria-label="Game log view">${button('recent','Recent games')}${links.regular?button('regular','Full regular season ('+links.regular.length+')'):''}${links.playoffs?button('playoffs','Playoffs ('+links.playoffs.length+')'):''}</div>`:'';
 if(active==='recent')return playerCard('RECENT GAME LOG',nav+(games.length?playerGameLog(games):'<p>No recent games in this competition view.</p>'));
 return playerCard(season+' '+(active==='regular'?'REGULAR SEASON':'PLAYOFFS')+' GAME LOG',nav+profileFullGameLog(p,links[active],active==='regular'?'Regular season':'Playoffs'));
}
function playerGameLog(games){return `<div class="scroll pp-game-log" tabindex="0" role="region" aria-label="Recent player game log; scroll horizontally for all statistics"><table><thead><tr><th scope="col">Day</th><th scope="col">Opponent</th><th scope="col">Stage</th>${gameBoxStatHeaders()}</tr></thead><tbody>${games.slice(-8).reverse().map(g=>`<tr><td>${g.day}</td><td>${escapeHTML(g.opponent)}</td><td>${escapeHTML(g.stage)}</td>${gameBoxStatCells(g)}</tr>`).join('')}</tbody></table></div><p>Swipe sideways for all stats. FG, 3PT and FT show makes–attempts. STA% is stamina at the end of the game. — means unavailable or no attempts.</p>`}
